function resolveIcon(fn, race) {
  if (!fn) return "";
  if (ICON_PATH_MAP_MAIN[fn]) return ICON_PATH_MAP_MAIN[fn];

  var r = (race && typeof race === "string") ? race.toLowerCase() : "";
  if (r.startsWith("sc2_")) {
    if (ICON_PATH_MAP_SC2[fn]) return ICON_PATH_MAP_SC2[fn];
    if (ICON_PATH_MAP_BW[fn]) return ICON_PATH_MAP_BW[fn];
  } else {
    if (ICON_PATH_MAP_BW[fn]) return ICON_PATH_MAP_BW[fn];
    if (ICON_PATH_MAP_SC2[fn]) return ICON_PATH_MAP_SC2[fn];
  }

  // Fallback: slash already in path → use as-is, otherwise prepend BW-icon/
  if (fn.indexOf("/") >= 0) return fn;
  return "BW-icon/" + fn;
}


