function getImg(id) {
  var u = (typeof getUnitData === "function") ? getUnitData(id) : null;
  var race = u ? u.race : "";
  return resolveIcon(IMG[id] || (id + "@scbw.png"), race);
}

function getIcons(race) {
  return RACE_ICONS[race] || DEFAULT_ICONS;
}

