      costItems: costs(m, g, buildTime), cost: { minerals: m || 0, gas: g || 0, supply: 0 }, buildTime: buildTime,
      requirements: req ? [req] : [], hp: hp, shields: 0, energy: 0, maxEnergy: 0, armor: armor, armorUpgrade: 0,
      sight: sight, detector: false, speed: speed || 0, attributes: attributes || "중장갑 · 생체 · 구조물", description: "",
      weapons: weapons || [], upgrades: upgrades || [], abilities: abilities || []
