// 유닛 모달에 적용 가능 연구 렌더링 (단일 카드)
function formatCostValue(cItem) {
  if (!cItem || cItem.value === undefined || cItem.value === null) return "";
  var val = cItem.value;
  var isTime = cItem.type === "time" || (cItem.icon && cItem.icon.indexOf("time") >= 0);
  if (isTime) {
    var num = Number(val);
    if (!isNaN(num)) {
      return fmtGameTime(num);
    }
  }
  return val;
}

function renderUnitApplicableUpgrades(u) {
  var title = document.getElementById("modal-unit-upgrades-title");
  var container = document.getElementById("modal-unit-upgrades-container");
  if (!title || !container) return;

  var isSc2TerranStructure = (u.race === "sc2_terran" && (u.type === "structure" || u.type === "building" || u.id === "sc2_auto_turret"));
  if ((u.type === "structure" || u.type === "building") && !isSc2TerranStructure) {
    title.style.display = "none";
    container.style.display = "none";
    return;
  }

  var refs = (UNIT_UPGRADE_REFS[u.id] || []).slice();
  if (isSc2TerranStructure) {
    if (u.id === "sc2_missile_turret" || u.id === "sc2_auto_turret" || u.id === "sc2_planetary_fortress") {
      refs.unshift({sid:"sc2_engineering_bay", name:"정밀 보안 자동추적기 연구"});
    }
    if (u.id !== "sc2_auto_turret") {
      refs.push({sid:"sc2_engineering_bay", name:"신소재 강철 장갑 연구"});
    }
  }
  if (!refs || refs.length === 0) {
    title.style.display = "none";
    container.style.display = "none";
    return;
  }

  var html = "";

  refs.forEach(function(ref) {
    var structure = UNIT_DATA.find(function(x) { return x.id === ref.sid; });
    if (!structure || !structure.upgrades) return;
    var upg = structure.upgrades.find(function(up) { return up.name === ref.name; });
    if (!upg) return;

    var iconSrc = upg.icon ? (resolveIcon(upg.icon)) : "";
    var imgTag = iconSrc
      ? "<img src='" + iconSrc + "' class='modal-item-icon' alt='' onerror=\"this.style.display='none';if(this.nextElementSibling)this.nextElementSibling.style.display='flex';\"/><div class='modal-item-icon-ph' style='display:none;'></div>"
      : "<div class='modal-item-icon-ph'></div>";

    var costBadgeHtml = "";
    if (upg.costItems && upg.costItems.length) {
      costBadgeHtml = "<div class='modal-item-cost-badge'>";
      upg.costItems.forEach(function(ci) {
        var cIcon = ci.icon ? (resolveIcon(ci.icon)) : "";
        var valCls = ci.type ? ("cost-val-" + ci.type) : "cost-val-default";
        costBadgeHtml += "<span class='cost-item-box'>" +
          (cIcon ? "<img src='" + cIcon + "' class='cost-item-icon' alt=''/>" : "") +
          "<span class='cost-item-val " + valCls + "'>" + formatCostValue(ci) + "</span></span>";
      });
      costBadgeHtml += "</div>";
    }

    // 스텟 영향 업그레이드 토글 키 확인
    var unitToggleMap = UNIT_UPGRADE_TOGGLE_KEYS[u.id] || {};
    var upgKey = unitToggleMap[upg.name];
    if (isSc2TerranStructure && u.id !== "sc2_auto_turret" && upg.name === "신소재 강철 장갑 연구") upgKey = "sc2_neosteel_frame";
    var isActive = upgKey && isUpgActive(upgKey);
    var rc = raceClr(u.race);
    var cardExtra = "";
    var cardClass = "modal-item-card" + (costBadgeHtml ? " has-cost-badge" : "");

    if (upgKey) {
      cardClass += " modal-upg-toggleable" + (isActive ? " modal-upg-active modal-upg-active-" + rc : "");
      cardExtra = " data-upg-key='" + upgKey + "' onclick=\"toggleUpg('" + upgKey + "')\" role='button' tabindex='0'";
    }

    html += "<div class='" + cardClass + "'" + cardExtra + ">";
    html += "  <div class='modal-item-icon-slot'>" + imgTag + "</div>";
    html += "  <div class='modal-item-content'>";
    html += "    <div class='modal-item-title'>" + upg.name + (isActive ? " <span class='upg-active-badge'>적용 중</span>" : "") + "</div>";
    var upgDesc = ref.desc || upg.desc;
    if (upgDesc) html += "    <div class='modal-item-desc'>" + upgDesc + "</div>";
    html += "  </div>";
    if (costBadgeHtml) html += costBadgeHtml;
    html += "</div>";
  });

  if (html) {
    title.style.display = "";
    container.style.display = "";
    container.innerHTML = html;
  } else {
    title.style.display = "none";
    container.style.display = "none";
  }
}

