  if (u.id === "sc2_mothership" && name === "시간 왜곡") meta = { duration: "10초", castRange: "9", cooldown: "84", effectRange: "3.75" };
  if (u.id === "sc2_mothership" && name === "은폐장") meta = { duration: "28초", cooldown: "70", effectRange: "6.25" };
